// ============================================================
// Validar payload — Code node (n8n), "Run Once for All Items"
// Simulador institucional (/simulador-de-economia) → n8n → Salesforce.
//
// Valida o JSON recebido pelo webhook ANTES de qualquer gravação
// (Drive ou Salesforce) e devolve um único item:
//   { valido, erro, fatura_presente, duplicado, dedupe_key, body }
// `body` é a cópia normalizada do que o formulário enviou; a fatura em
// base64 segue só em `body.fatura_base64` (o campo `fatura`, mantido no
// contrato por compatibilidade com a PageConv, é aceito como alternativa).
// Nenhum dado pessoal é devolvido nas respostas de erro.
// ============================================================

// Regra comercial do formulário: a fatura é obrigatória NO FRONT-END.
// Aqui fica false para que um lead nunca seja descartado só por falta
// do arquivo (ele segue para o Salesforce sem link de fatura).
const EXIGIR_FATURA = false;

const MAX_FATURA_BYTES = 10 * 1024 * 1024; // mesmo limite do formulário (10 MB)
const TIPOS_FATURA = ['application/pdf', 'image/jpeg', 'image/png'];
const ESTADOS = ['GO', 'TO', 'PR', 'MG', 'MT'];
const TIPOS_CONTA = ['Residencial', 'Comercial', 'Industrial'];
const TITULAR = ['Sim', 'Não', 'Nao'];
const JANELA_DUPLICIDADE_MS = 10 * 60 * 1000; // 10 min

const raw = $input.first().json.body;
const body = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : null;

const str = (v, max = 255) => String(v ?? '').trim().slice(0, max);
const isTrue = (v) => v === true || String(v ?? '').trim().toLowerCase() === 'true';

function falha(erro) {
  return [{ json: { valido: false, erro, fatura_presente: false, duplicado: false } }];
}

if (!body) return falha('payload_invalido');

// ---------- campos obrigatórios ----------
const nome = str(body.nome, 120);
const whatsDigits = String(body.whatsapp || body.telefone_sf || '').replace(/\D/g, '');
const email = str(body.email || body.email_sf, 120).toLowerCase();
const estado = str(body.estado, 2).toUpperCase();
const valorConta = str(body.valor_conta, 60);
const tipo = str(body.tipo, 30);
const titular = str(body.titular, 10);

const faltando =
  nome.length < 2 ||
  whatsDigits.length < 10 || whatsDigits.length > 13 ||
  (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) ||
  !ESTADOS.includes(estado) ||
  !valorConta ||
  !TIPOS_CONTA.includes(tipo) ||
  !TITULAR.includes(titular) ||
  !isTrue(body.lgpd);
if (faltando) return falha('payload_invalido');

// ---------- fatura (base64, sem o prefixo data:) ----------
let base64 = String(body.fatura_base64 || body.fatura || '').replace(/\s+/g, '');
if (base64.startsWith('data:')) base64 = base64.slice(base64.indexOf(',') + 1);
const faturaPresente = base64.length > 0;

if (!faturaPresente && EXIGIR_FATURA) {
  return falha('fatura_ausente');
}

let faturaTipo = str(body.fatura_tipo, 60).toLowerCase();
let faturaBytes = 0;
if (faturaPresente) {
  if (!/^[A-Za-z0-9+/]+={0,2}$/.test(base64) || base64.length % 4 !== 0) return falha('fatura_invalida');
  const padding = base64.endsWith('==') ? 2 : base64.endsWith('=') ? 1 : 0;
  faturaBytes = (base64.length / 4) * 3 - padding;
  if (faturaBytes <= 0 || faturaBytes > MAX_FATURA_BYTES) return falha('fatura_invalida');

  // Confere o tipo real pelo início do arquivo (não confia só no MIME enviado).
  const head = Buffer.from(base64.slice(0, 16), 'base64');
  const real =
    head.slice(0, 4).toString('latin1') === '%PDF' ? 'application/pdf'
    : head[0] === 0xff && head[1] === 0xd8 && head[2] === 0xff ? 'image/jpeg'
    : head[0] === 0x89 && head.slice(1, 4).toString('latin1') === 'PNG' ? 'image/png'
    : '';
  if (!real || (faturaTipo && faturaTipo !== real && !(faturaTipo === 'image/jpg' && real === 'image/jpeg'))) {
    return falha('fatura_invalida');
  }
  faturaTipo = real;
}
if (faturaPresente && !TIPOS_FATURA.includes(faturaTipo)) return falha('fatura_invalida');

// Nome do arquivo sem caminho nem caracteres de controle.
const ext = { 'application/pdf': '.pdf', 'image/jpeg': '.jpg', 'image/png': '.png' }[faturaTipo] || '';
let faturaNome = str(body.fatura_nome, 120).replace(/[\\/:*?"<>|\u0000-\u001f]/g, '').trim();
if (faturaPresente && !faturaNome) faturaNome = 'fatura' + ext;

// ---------- duplicidade ----------
// Mesmo WhatsApp + e-mail + faixa de valor + tamanho da fatura em até 10 min.
// Guarda só um hash (sem dados pessoais) em staticData; vale para execuções
// de produção (workflow ativo). O registro é feito em "Registrar envio",
// depois do Salesforce confirmar, para não bloquear um reenvio após falha.
function fnv1a(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}
const dedupeKey = fnv1a([whatsDigits.slice(-11), email, valorConta, faturaBytes].join('|'));
const store = $getWorkflowStaticData('global');
const agora = Date.now();
store.envios = store.envios || {};
for (const [k, t] of Object.entries(store.envios)) if (agora - t > JANELA_DUPLICIDADE_MS) delete store.envios[k];
const duplicado = Boolean(store.envios[dedupeKey]);

return [{
  json: {
    valido: true,
    erro: '',
    fatura_presente: faturaPresente,
    duplicado,
    dedupe_key: dedupeKey,
    body: {
      ...body,
      nome,
      email,
      estado,
      valor_conta: valorConta,
      tipo,
      titular,
      fatura: '',
      fatura_base64: base64,
      fatura_anexada: faturaPresente ? 'true' : 'false',
      fatura_nome: faturaPresente ? faturaNome : '',
      fatura_tipo: faturaPresente ? faturaTipo : '',
      fatura_tamanho: faturaPresente ? String(faturaBytes) : '',
    },
  },
}];

// ============================================================
// Juntar pasta e fatura — Code node (n8n), "Run Once for All Items"
// Substitui o "Merge1" do workflow da PageConv: recebe a pasta criada no
// Drive e devolve, num único item, o id da pasta e os dados da fatura que o
// nó "Base64 → Arquivo" (o mesmo da PageConv) converte em binário.
// ============================================================

const pasta = $input.first().json;
const body = $('Validar payload').first().json.body;

if (!pasta || !pasta.id) throw new Error('pasta_drive_sem_id');

return [{
  json: {
    pasta_id: pasta.id,
    fatura_base64: body.fatura_base64,
    fatura_nome: body.fatura_nome,
    fatura_tipo: body.fatura_tipo,
  },
}];

// ============================================================
// Preparar Lead — Code node (n8n), "Run Once for All Items"
// Base: "Preparar Lead1" do workflow "LP PageConv - Criação do SalesForce"
// (Padrão UTM v5.2, mesmos nomes e fallbacks). Mudanças para o simulador
// institucional estão marcadas com [SIMULADOR].
// ============================================================

// [SIMULADOR] Produção: macros não resolvidas ({{campaign.name}}, {campaignid},
// __PLACEMENT__) não vão para o CRM. Para depurar mapeamento, mude para false.
const LIMPAR_MACROS = true;

// [SIMULADOR] Lê o payload já validado (e não o webhook bruto).
const validado = $('Validar payload').first().json;
const body = validado.body || {};

// ------------------------------------------------------------
// HELPERS (iguais ao original)
// ------------------------------------------------------------

// Macros de plataforma que NAO foram resolvidas.
// Meta: {{campaign.name}} | Google: {campaignid} | TikTok: __CAMPAIGN_ID__
const MACRO_NAO_RESOLVIDA = /^(\{\{.*\}\}|\{[^{}]*\}|__.*__)$/;

function clean(v) {
  const s = String(v ?? '').trim();
  if (!s) return '';
  const low = s.toLowerCase();
  if (low === 'undefined' || low === 'null') return '';
  if (LIMPAR_MACROS && MACRO_NAO_RESOLVIDA.test(s)) return '';
  return s;
}

function pick(...vals) {
  for (const v of vals) {
    const c = clean(v);
    if (c) return c;
  }
  return '';
}

function boolOf(v) {
  return v === true || String(v ?? '').trim().toLowerCase() === 'true';
}

function cut(v, max) {
  const s = clean(v);
  return s.length > max ? s.slice(0, max) : s;
}

// [SIMULADOR] Campos texto do Salesforce: no máximo 255 caracteres.
const t = (v) => cut(v, 255);

// Telefone -> formato Salesforce (DD) 9XXXX-XXXX
function telSF(raw) {
  let d = String(raw || '').replace(/\D/g, '');
  if (d.length > 11 && d.startsWith('55')) d = d.slice(2);
  if (d.length === 10) d = d.slice(0, 2) + '9' + d.slice(2);
  if (d.length !== 11) return String(raw || '');
  return `(${d.slice(0, 2)}) ${d.slice(2, 7)}-${d.slice(7)}`;
}

// ------------------------------------------------------------
// FATURA (Drive)
// [SIMULADOR] Distingue "sem fatura" de "upload falhou": se o Drive falhar,
// o lead é criado mesmo assim e a falha fica registrada na descrição.
// ------------------------------------------------------------

let faturaUrl = '';
try {
  const up = $('Upload da fatura').first().json;
  if (up && up.id && !up.error) faturaUrl = `https://drive.google.com/file/d/${up.id}/view`;
} catch (e) {
  faturaUrl = ''; // branch sem anexo, ou a pasta não foi criada
}
const faturaStatus = !validado.fatura_presente ? 'sem_fatura' : faturaUrl ? 'anexada' : 'upload_falhou';

// ------------------------------------------------------------
// CAMPOS DERIVADOS / FALLBACKS (iguais ao original)
// ------------------------------------------------------------

// utm_project_id virou utm_campaign_code.
// FALLBACK PERMANENTE: existe QR code impresso que nao pode ser reemitido.
const campaignCode = pick(body.utm_campaign_code, body.utm_project_id);

// utm_adgroup foi unificado em utm_adset.
const adset = pick(body.utm_adset, body.utm_adgroup);
const adsetId = pick(body.utm_adset_id, body.utm_adgroup_id);

const cidade = pick(body.cidade, body.utm_city);
const estado = pick(body.estado, body.utm_state);

// ------------------------------------------------------------
// [SIMULADOR] Identificação da origem institucional. Campos próprios,
// sem sobrescrever utm_source/utm_campaign_code/utm_lp reais.
// ------------------------------------------------------------
const leadOrigin = pick(body.origem_site) || 'site_institucional';
const leadForm = pick(body.form_name, body.origem_formulario) || 'simulador_institucional';
const pagePath = pick(body.origem_pagina, body.page_path) || '/simulador-de-economia';

const nome = cut(body.nome, 80);

// [SIMULADOR] Company é obrigatório no Lead do Salesforce e o formulário não
// coleta empresa. Padrão do Salesforce para pessoa física/lead sem empresa:
// usar o nome da pessoa. Não é inventado nenhum dado comercial.
const company = nome;

// [SIMULADOR] Dados do formulário sem campo próprio no mapeamento original
// (tipo de conta, titularidade, consentimento LGPD, origem e situação da
// fatura) vão para o campo padrão Description, sem criar campos no CRM.
const statusFaturaTexto = {
  anexada: 'anexada (link no campo Link da fatura)',
  sem_fatura: 'não enviada',
  upload_falhou: 'enviada pelo visitante, mas o upload no Drive falhou; solicitar reenvio',
}[faturaStatus];
const descricao = [
  'Lead do simulador de economia do site institucional.',
  `Tipo de conta: ${clean(body.tipo) || '-'}`,
  `Titular da conta: ${clean(body.titular) || '-'}`,
  `Consentimento LGPD: ${boolOf(body.lgpd) ? 'sim' : 'não'}${clean(body.created_at) ? ` (${clean(body.created_at)})` : ''}`,
  `Fatura: ${statusFaturaTexto}`,
  `Origem: ${leadOrigin} · formulário ${leadForm} · página ${pagePath}`,
].join('\n');

// ------------------------------------------------------------
// PAYLOAD (mesmos campos do original + os marcados [SIMULADOR])
// ------------------------------------------------------------

return [{
  json: {
    // --- dados do formulario ---
    nome,
    company,
    email: clean(body.email || body.email_sf).toLowerCase(),
    telefone_sf: telSF(body.whatsapp || body.telefone_sf),
    cidade: t(cidade),
    estado: t(estado),
    valor_conta: t(body.valor_conta),
    tipo: t(body.tipo),
    titular: t(body.titular),
    lgpd: boolOf(body.lgpd),

    // --- fatura ---
    fatura_url: faturaUrl,
    fatura_status: faturaStatus,
    fatura_anexada: boolOf(body.fatura_anexada),
    fatura_nome: t(body.fatura_nome),
    fatura_tipo: t(body.fatura_tipo),
    fatura_tamanho: t(body.fatura_tamanho),

    // --- rastreio / contexto ---
    lead_source: t(body.lead_source),
    origem_formulario: t(body.origem_formulario),
    lead_origin: leadOrigin,
    lead_form: leadForm,
    gclid: t(body.gclid),
    page_url: t(body.page_url),
    page_url_full: t(body.page_url_full),
    page_path: pagePath,
    created_at: t(body.created_at),
    descricao,

    // --- identificacao da origem ---
    utm_source: t(body.utm_source),
    utm_medium: t(body.utm_medium),
    utm_font: t(body.utm_font),
    utm_channel: t(body.utm_channel),
    utm_placement: t(body.utm_placement),

    // --- campanha BC (interna) ---
    utm_campaign_code: t(campaignCode),
    utm_campaign: t(body.utm_campaign),
    utm_campaign_id: t(body.utm_campaign_id),
    utm_link_id: t(body.utm_link_id),

    // --- hierarquia do gerenciador de anuncios ---
    utm_adcampaign: t(body.utm_adcampaign),
    utm_adcampaign_id: t(body.utm_adcampaign_id),
    utm_adset: t(adset),
    utm_adset_id: t(adsetId),
    utm_content: t(body.utm_content),
    utm_content_id: t(body.utm_content_id),
    utm_term: t(body.utm_term),

    // --- originador / vendedor ---
    utm_originator: t(body.utm_originator),
    utm_seller: t(body.utm_seller),

    // --- classificacao ---
    utm_product: t(body.utm_product),
    utm_segment: t(body.utm_segment),
    utm_public: t(body.utm_public),
    utm_region: t(body.utm_region),
    utm_state: t(body.utm_state),
    utm_city: t(body.utm_city),
    utm_offer: t(body.utm_offer),
    utm_objective: t(body.utm_objective),
    utm_contract: t(body.utm_contract),
    utm_lp: t(body.utm_lp),
    utm_id: t(body.utm_id),

    // --- legado (mantidos pra nao quebrar mapeamento existente) ---
    utm_project_id: t(body.utm_project_id),
    utm_adgroup: t(body.utm_adgroup),
    utm_adgroup_id: t(body.utm_adgroup_id),
  },
}];

// ============================================================
// Registrar envio — Code node (n8n), "Run Once for All Items"
// Roda só depois do Salesforce confirmar a criação do lead: guarda o hash
// do envio (sem dados pessoais) para barrar reenvios iguais por 10 min e
// devolve o id do lead para a resposta ao formulário.
// ============================================================

const lead = $input.first().json;
const { dedupe_key: chave } = $('Validar payload').first().json;

if (!lead || !lead.id) throw new Error('salesforce_sem_id');

const store = $getWorkflowStaticData('global');
store.envios = store.envios || {};
if (chave) store.envios[chave] = Date.now();

return [{ json: { lead_id: lead.id, fatura_status: $('Preparar Lead').first().json.fatura_status } }];
